fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Calculate the difference
    let diff = a.wrapping_sub(b);
    
    // Check if the absolute difference is strictly less than tolerance
    // We need to handle potential overflow when taking absolute value
    if diff == i8::MIN {
        // Special case: i8::MIN.abs() would overflow, but since tolerance is positive,
        // i8::MIN is definitely not within tolerance (it's -128)
        false
    } else {
        diff.abs() < tol
    }
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions guarantee arrays have equal positive length
    // and tol is strictly positive
    
    let mut result = Vec::with_capacity(a.len());
    
    for i in 0..a.len() {
        result.push(is_close_i8(a[i], b[i], tol));
    }
    
    result
}